mapper.select:
SELECT r.date
FROM sj_day_record r
WHERE r.user_id = #{userId}
  AND r.date <= #{today}
  AND (
      (r.mood IS NOT NULL AND TRIM(r.mood) != '')
      OR (r.diary IS NOT NULL AND TRIM(r.diary) != '')
      OR EXISTS (
          SELECT 1 FROM sj_learning_item i WHERE i.record_id = r.id
      )
  )
ORDER BY r.date DESC
